begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('60000000-0000-0000-0000-000000000001','parent-a@example.test',now(),'{"role":"ADMIN"}'),
('60000000-0000-0000-0000-000000000002','parent-b@example.test',now(),'{}'),
('60000000-0000-0000-0000-000000000003','unverified@example.test',null,'{}'),
('60000000-0000-0000-0000-000000000004','student@example.test',now(),'{}');
insert into public.users(id,role) values ('60000000-0000-0000-0000-000000000004','STUDENT');
insert into public.consent_policies values ('ai_tutoring','test-v1','Synthetic approved policy for transactional tests only',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000003',true);
select throws_ok($$select public.provision_parent()$$,'42501',null,'unverified account cannot provision');
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000004',true);
select throws_ok($$select public.provision_parent()$$,'42501',null,'student cannot become a parent');
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.provision_parent()$$,'verified signup provisions parent');
select lives_ok($$select public.provision_parent()$$,'provisioning retry is idempotent');
select is((select count(*)::integer from public.parent_profiles),1,'one parent profile after repeated provisioning');
select is((select role::text from public.users where id=auth.uid()),'PARENT','metadata ADMIN role ignored');
select lives_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000001','Alex',8,'Fractions')$$,'parent creates minimal student');
select lives_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000001','Alex',8,'Fractions')$$,'student creation retry succeeds');
select is((select count(*)::integer from public.student_profiles),1,'retry creates one student');
select is((select count(*)::integer from public.parent_student_relationships),1,'retry creates one relationship');
select ok((select user_id is null from public.student_profiles),'no minor login credentials provisioned');
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000001','Other',8,null)$$,'22023',null,'conflicting retry rejected');
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000002',' ',8,null)$$,'22023',null,'blank display name rejected');
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000002','Alex',13,null)$$,'22023',null,'invalid grade rejected');
select throws_ok($$select public.create_parent_student(null,'Alex',8,null)$$,'22023',null,'missing idempotency key rejected');
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000002','Alex',8,repeat('x',501))$$,'22023',null,'oversized goals rejected');
select is((select count(*)::integer from public.student_profiles),1,'failed writes create no partial student');
select lives_ok($$select public.update_parent_student((select id from public.student_profiles),'Alex edited',9,'Algebra')$$,'authorized parent edits minimal fields');
select is((select display_name from public.student_profiles),'Alex edited','edit persists');
select throws_ok($$update public.student_profiles set user_id='60000000-0000-0000-0000-000000000004'$$,'42501',null,'browser cannot assign student login');
select throws_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000001',(select id from public.student_profiles),'microphone','draft-v1',true)$$,'22023',null,'draft policy cannot receive grant');
select lives_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000001',(select id from public.student_profiles),'ai_tutoring','test-v1',true)$$,'approved policy grants can be recorded');
select lives_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000001',(select id from public.student_profiles),'ai_tutoring','test-v1',true)$$,'consent retries idempotent');
select is((select count(*)::integer from public.consents),1,'one grant after duplicate request');
select lives_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000002',(select id from public.student_profiles),'ai_tutoring','test-v1',false)$$,'parent can withdraw consent');
select is((select count(*)::integer from public.consents),2,'grant and withdrawal both preserved');
select is((select granted from public.consents order by event_order desc limit 1),false,'latest decision is withdrawn');
select ok((select bool_and(parent_id=auth.uid() and policy_version='test-v1' and source='parent_portal' and recorded_at is not null) from public.consents),'consent records actor, version, source and time');
select throws_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000002',(select id from public.student_profiles),'ai_tutoring','test-v1',true)$$,'22023',null,'conflicting consent retries rejected');
select throws_ok($$update public.consents set granted=true$$,'42501',null,'parent cannot overwrite consent history');
select throws_ok($$update public.consent_policies set approved=true$$,'42501',null,'parent cannot approve policy');
reset role;
-- Capture the first family's ID without granting access to it.
select set_config('test.other_student',(select id::text from public.student_profiles where created_by='60000000-0000-0000-0000-000000000001'),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000002',true);
select lives_ok($$select public.provision_parent()$$,'second parent provisions independently');
select is((select count(*)::integer from public.student_profiles),0,'unrelated parent cannot read first child');
select is((select count(*)::integer from public.consents),0,'unrelated parent cannot read consent history');
select throws_ok($$select public.update_parent_student(current_setting('test.other_student')::uuid,'Forged',8,null)$$,'42501',null,'URL target cannot authorize unrelated child edit');
select throws_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000003',current_setting('test.other_student')::uuid,'ai_tutoring','test-v1',false)$$,'42501',null,'unrelated parent cannot withdraw consent');
select lives_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000001','Other family',8,null)$$,'same request UUID scoped independently per parent');
select is((select count(*)::integer from public.student_profiles),1,'second parent sees own child only');
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000004',true);
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000003','Forged',8,null)$$,'42501',null,'student cannot create profiles');
select throws_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000003',current_setting('test.other_student')::uuid,'ai_tutoring','test-v1',true)$$,'42501',null,'student cannot grant consent');
reset role;
set local role service_role;
select throws_ok($$update public.consents set granted=true$$,'42501',null,'service cannot silently overwrite history');
select throws_ok($$delete from public.consents$$,'42501',null,'service cannot silently delete history');
reset role;
select throws_ok($$update public.consent_policies set description='Rewritten wording' where version='test-v1'$$,'42501',null,'approved policy wording cannot be silently rewritten');
-- Existing evidence is retained after a policy is retired; withdrawals still work.
update public.consent_policies set approved=false where version='test-v1';
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.record_parent_consent('80000000-0000-0000-0000-000000000004',current_setting('test.other_student')::uuid,'ai_tutoring','test-v1',false)$$,'withdrawal allowed after approval is removed');
reset role;
insert into public.audit_logs(actor_id,action) select '60000000-0000-0000-0000-000000000001','identity.test' from generate_series(1,30);
set local role authenticated;
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000003','Rate limited',8,null)$$,'P0001',null,'per-parent successful mutation limit enforced');
reset role;
set local role anon;
select throws_ok($$select public.provision_parent()$$,'42501',null,'anonymous provisioning denied');
select throws_ok($$select public.create_parent_student('70000000-0000-0000-0000-000000000003','Anonymous',8,null)$$,'42501',null,'anonymous profile creation denied');
reset role;
select * from finish();
rollback;
